func Mcp_static_handle(host *McpHost, caller *Caller, msg *MfJ) *MfJ {
  if  msg.isObj() == false {
    return Mcp_static_error(CreateNew_MfJ(), int64(-32600), "Invalid Request")
  }
  var method string= msg.str_("method");
  var hasId bool= msg.has("id");
  var id *MfJ= msg.field("id");
  if  int64(len(method)) == int64(0) {
    if  msg.has("result") || msg.has("error") {
      return CreateNew_MfJ()
    }
    return Mcp_static_error(id, int64(-32600), "Invalid Request")
  }
  if  hasId == false {
    return CreateNew_MfJ()
  }
  var params *MfJ= msg.field("params");
  if  method == "initialize" {
    return Mcp_static_ok(id, Mcp_static_initialize(host, params))
  }
  if  method == "ping" {
    return Mcp_static_ok(id, MfJ_static_newObj())
  }
  if  method == "tools/list" {
    var tl *MfJ= MfJ_static_newObj();
    tl.put("tools", Tools_static_list());
    return Mcp_static_ok(id, tl)
  }
  if  method == "tools/call" {
    var name string= params.str_("name");
    var r *MfJ= Tools_static_call(host, caller, name, params.field("arguments"));
    if  r.kind == int64(0) {
      return Mcp_static_error(
        id,
        int64(-32602),
        (("MCP error -32602: Tool " + name) + " not found"),
      )
    }
    return Mcp_static_ok(id, r)
  }
  if  method == "resources/list" {
    var rl *MfJ= MfJ_static_newObj();
    rl.put("resources", Tools_static_resources(host.BaseURL()));
    return Mcp_static_ok(id, rl)
  }
  if  method == "resources/templates/list" {
    var tl2 *MfJ= MfJ_static_newObj();
    tl2.put("resourceTemplates", MfJ_static_newArr());
    return Mcp_static_ok(id, tl2)
  }
  if  method == "resources/read" {
    var uri string= params.str_("uri");
    var rr *MfJ= Tools_static_read(host, uri);
    if  rr.kind == int64(0) {
      return Mcp_static_error(id, int64(-32002), (("Resource " + uri) + " not found"))
    }
    return Mcp_static_ok(id, rr)
  }
  return Mcp_static_error(id, int64(-32601), "Method not found")
}
func Mcp_static_post(host *McpHost, caller *Caller, body string) *McpReply {
  var reply *McpReply= CreateNew_McpReply();
  if  int64(len(body)) == int64(0) {
    reply.status = int64(400); 
    reply.body = JOut_static_text(Mcp_static_error(
      CreateNew_MfJ(),
      int64(-32700),
      "Parse error: Invalid JSON",
    )); 
    return reply
  }
  var msg *MfJ= MfJ_static_parse(body);
  if  msg.isArr() {
    var answers *MfJ= MfJ_static_newArr();
    for _, m := range msg.arr {
      var a *MfJ= Mcp_static_handle(host, caller, m);
      if  a.kind != int64(0) {
        answers.add(a);
      }
    }
    if  answers.count() == int64(0) {
      reply.status = int64(202); 
      return reply
    }
    reply.body = JOut_static_text(answers); 
    return reply
  }
  var one *MfJ= Mcp_static_handle(host, caller, msg);
  if  one.kind == int64(0) {
    reply.status = int64(202); 
    return reply
  }
  reply.body = JOut_static_text(one); 
  return reply
}
