func App_static_cors(res http.ResponseWriter) () {
  res.Header().Set("Access-Control-Allow-Origin", "*")
  res.Header().Set("Access-Control-Allow-Headers", "content-type, mcp-session-id, mcp-protocol-version, authorization, last-event-id")
  res.Header().Set("Access-Control-Expose-Headers", "mcp-session-id, mcp-protocol-version, www-authenticate")
  res.Header().Set("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
}
func App_static_sendJson(res http.ResponseWriter, status int64, body string) () {
  res.Header().Set("Content-Type", "application/json; charset=utf-8")
  res.WriteHeader(int(status))
  res.Write([]byte(body))
}
func App_static_redirect(res http.ResponseWriter, url string) () {
  res.Header().Set("Location", url)
  res.WriteHeader(int(int64(302)))
}
func App_static_send(res http.ResponseWriter, out *HttpOut) () {
  if  int64(len(out.redirect)) > int64(0) {
    App_static_redirect(res, out.redirect);
    return
  }
  if  int64(len(out.text)) > int64(0) {
    res.Header().Set("Content-Type", "text/plain; charset=utf-8")
    res.WriteHeader(int(out.status))
    res.Write([]byte(out.text))
    return
  }
  if  out.noStore {
    res.Header().Set("Cache-Control", "no-store")
  }
  App_static_sendJson(res, out.status, JOut_static_text(out.json));
}
func App_static_originOf(host *McpHost, req *http.Request) string {
  var base string= host.BaseURL();
  var h string= req.Header.Get("X-Forwarded-Host");
  if  int64(len(h)) == int64(0) {
    h = req.Header.Get("Host"); 
  }
  if  int64(len(h)) == int64(0) {
    h = req.Host; 
  }
  var comma int64= int64(strings.Index(h, ","));
  if  comma >= int64(0) {
    h = h[int64(0):comma]; 
  }
  h = strings.TrimSpace(h); 
  var https string= "https://" + h;
  if  (https == "https://sliqtly.com" || https == "https://sliqtly.web.app") || https == base {
    return https
  }
  if  host.TrustHost() && int64(len(h)) > int64(0) {
    if  host.TLS() {
      return "https://" + h
    }
    return "http://" + h
  }
  return base
}
func App_static_rpcError(code int64, message string) string {
  return JOut_static_text(Mcp_static_error(CreateNew_MfJ(), code, message))
}
func App_static_serve(host *McpHost, req *http.Request, res http.ResponseWriter) () {
  App_static_cors(res);
  var method string= req.Method;
  var path string= req.URL.Path;
  if  method == "OPTIONS" {
    res.WriteHeader(int(int64(204)))
    return
  }
  if  host.OAuthOn() {
    if  App_static_serveOAuth(host, req, res, method, path) {
      return
    }
  }
  if  path == "/mcp" {
    App_static_serveMcp(host, req, res, method);
    return
  }
  res.Header().Set("Content-Type", "text/plain; charset=utf-8")
  res.WriteHeader(int(int64(404)))
  res.Write([]byte((("Cannot " + method) + " ") + path))
}
func App_static_serveOAuth(host *McpHost, req *http.Request, res http.ResponseWriter, method string, path string) bool {
  if  method == "GET" {
    if  path == "/.well-known/oauth-protected-resource" || path == "/.well-known/oauth-protected-resource/mcp" {
      App_static_sendJson(
        res,
        int64(200),
        JOut_static_text(OAuth_static_resourceMetadata(App_static_originOf(host, req))),
      );
      return true
    }
    if  path == "/.well-known/oauth-authorization-server" || path == "/.well-known/openid-configuration" {
      App_static_sendJson(
        res,
        int64(200),
        JOut_static_text(OAuth_static_metadata(App_static_originOf(host, req))),
      );
      return true
    }
    if  path == "/oauth/authorize" {
      var q *MfJ= J_static_parse(queryJSON(req));
      App_static_send(res, OAuth_static_authorize(host, q, App_static_originOf(host, req)));
      return true
    }
    return false
  }
  if  method != "POST" {
    return false
  }
  if  (path != "/oauth/register" && path != "/oauth/approve") && path != "/oauth/token" {
    return false
  }
  var body *MfJ= J_static_parse(host.BodyJSON());
  if  body.isObj() == false {
    body = MfJ_static_newObj(); 
  }
  if  path == "/oauth/register" {
    App_static_send(res, OAuth_static_register(host, body));
  }
  if  path == "/oauth/approve" {
    App_static_send(res, OAuth_static_approve(host, body));
  }
  if  path == "/oauth/token" {
    App_static_send(res, OAuth_static_token(host, body));
  }
  return true
}
func App_static_serveMcp(host *McpHost, req *http.Request, res http.ResponseWriter, method string) () {
  var accept string= req.Header.Get("Accept");
  if  method == "GET" && int64(strings.Index(accept, "text/event-stream")) < int64(0) {
    App_static_redirect(res, host.BaseURL() + "/connect.html");
    return
  }
  if  method != "POST" {
    res.Header().Set("Allow", "POST")
    App_static_sendJson(
      res,
      int64(405),
      App_static_rpcError(int64(-32000), "Method not allowed: this server is stateless, POST only."),
    );
    return
  }
  var caller *Caller= CreateNew_Caller();
  if  host.OAuthOn() {
    var origin string= App_static_originOf(host, req);
    var w *Who= OAuth_static_who(host, req.Header.Get("Authorization")); _ = w
    if  w.state == int64(3) {
      host.Log("token check failed: " + host.Err())
      App_static_sendJson(res, int64(500), App_static_rpcError(int64(-32603), "Internal error"));
      return
    }
    if  w.state == int64(2) {
      res.Header().Set("WWW-Authenticate", ("Bearer error=\"invalid_token\", resource_metadata=\"" + origin) + "/.well-known/oauth-protected-resource/mcp\"")
      App_static_sendJson(
        res,
        int64(401),
        App_static_rpcError(int64(-32001), "The sign-in has expired."),
      );
      return
    }
    if  w.state == int64(1) {
      caller.signedIn = true; 
      caller.uid = w.uid; 
      caller.name = w.name; 
    }
    caller.signIn = origin + "/.well-known/oauth-protected-resource/mcp"; 
  }
  var ip string= req.Header.Get("X-Forwarded-For");
  var comma int64= int64(strings.Index(ip, ","));
  if  comma >= int64(0) {
    ip = ip[int64(0):comma]; 
  }
  ip = strings.TrimSpace(ip); 
  if  int64(len(ip)) == int64(0) {
    ip = host.RemoteIP(); 
  }
  caller.who = ip; 
  if  caller.signedIn {
    caller.who = "uid:" + caller.uid; 
  }
  if  int64(strings.Index(accept, "application/json")) < int64(0) || int64(strings.Index(accept, "text/event-stream")) < int64(0) {
    App_static_sendJson(
      res,
      int64(406),
      App_static_rpcError(int64(-32000), "Not Acceptable: Client must accept both application/json and text/event-stream"),
    );
    return
  }
  if  int64(strings.Index(strings.ToLower(req.Header.Get("Content-Type")), "application/json")) < int64(0) {
    App_static_sendJson(
      res,
      int64(415),
      App_static_rpcError(int64(-32000), "Unsupported Media Type: Content-Type must be application/json"),
    );
    return
  }
  var pv string= req.Header.Get("Mcp-Protocol-Version");
  if  int64(len(pv)) > int64(0) && Deck_static_inList(Mcp_static_VERSIONS(), pv) == false {
    App_static_sendJson(
      res,
      int64(400),
      App_static_rpcError(int64(-32000), ("Bad Request: Unsupported protocol version: " + pv)),
    );
    return
  }
  var reply *McpReply= Mcp_static_post(host, caller, host.BodyJSON()); _ = reply
  if  reply.status == int64(202) {
    res.WriteHeader(int(int64(202)))
    return
  }
  App_static_sendJson(res, reply.status, reply.body);
}
